nodes.statement:
Bartolucci-De Marchis-Malchiodi obtained a very general existence theorem \cite[Theorem 1.1]{BdMM11} on the same problem in supercritical regimes. In particular, they showed that there exists a cone spherical metric representing the effective divisor $D = \sum_{j = 1}^n \, \beta_j p_j$ on $X$ if the following conditions hold:
\begin{itemize}
\item $g_X \geq 1$ and $\beta_j>0$ for all $1\leq j\leq n$,
\item $2-2g_X+\deg\, D$ is greater than $2$ and does not belong to the  discrete subset
$\left \{ \mu > 0 \mid \mu = 2k + 2 \sum_{j=1}^n n_j (1 + \beta_j ), k \in \mathbb{Z}_{\geq 0}, n_j \in \{ 0,1\} \right \}$ of ${\Bbb R}$.
\end{itemize}

Let $X$ be a compact connected Riemann surface of genus $g_X \geq 1$. Then there exists a canonical surjective map $\sigma \colon {\mathcal {SE}}(X)\to {\mathcal {MI}}(X,\,{\Bbb Z})$ such that
\begin{enumerate}

\item the irreducible metric corresponding to an equivalence class of a stable extension $0\to L_1\to E\to L_2\to 0$ represents an effective divisor lying  in the complete linear system $\left| L_1^{-2} \otimes \det E \otimes K_{X} \right|$, where two stable extensions are called {\rm equivalent} if and only if one of them is obtained from the other by tensoring a line bundle;


\item an irreducible metric representing an effective divisor has at most $2^{2g_{X}}$ preimages under $\sigma$; and

\item if $g_X \geq 2$ and the index $k >  10g_{X} - 5$, the restriction of $\sigma$ to some Zariski open subset of ${\mathcal {SE}}_k(X)$ is injective.
\end{enumerate}

Let $X$ be a compact Riemann surface of genus $g_{X}\geq 1$, and let $L_{1}, L_{2}$ be two line bundles of degrees $d_{1}, d_{2}$ respectively. Suppose that either one of the following conditions holds:
\begin{itemize}
\item $d_{2} - d_{1}$ is a positive odd integer and $g_{X}=1$;
\item $d_{2} - d_{1}$ is a positive integer and $g_{X} \geq 2$.
\end{itemize}
Then there always exists a stable extension $E$ of $L_{2}$ by $L_{1}$.
Moreover, the set of unstable extensions forms an affine subvariety of codimension $\geq g_{X}$ {\rm \big(}resp. $\geq (g_{X} - 1)${\rm \big)} in the extension space $\operatorname{Ext}_{X}^{1}(L_{2}, L_{1})$ if $d_{2} - d_{1}$ is odd (resp. even).
Furthermore, if $d_{2} - d_{1} = 1$, then each nontrivial extension of $L_2$ by $L_1$ is stable.

Then we obtain the following commutative diagram
\[\xymatrix{
\mathcal A^{0}(L)\ar[r] ^-{i}\ar[drr]_-{\theta_{\Bbb E}} & \mathcal A^{0}(E)\ar[r] ^-{\partial_{E}} & E\otimes \mathcal{A}^{1,0}\ar[d]^-{p \otimes \operatorname{id}} \\
 & & M \otimes \mathcal{A}^{1,0}
}\]
where $p \otimes \operatorname{id}$ is induced by $E \rightarrow E/L \cong M$ and $\theta_{\Bbb E} := (p \otimes \operatorname{id}) \circ \partial_{E} \circ i$.

The Chern connection $D_{E}$ of $E$ could be expressed by
\[ D_{E} = \begin{pmatrix}
D_{L} & -\beta \\
\beta^{*_{h}} & D_{M}
\end{pmatrix}, \]
where $\beta^{*_{h}}$ is the second fundamental form of $L$ in $E$.

Let $D$ be an effective divisor of degree ${\rm even}=d>2g_X-2$ on a compact Riemann surface $X$ of genus $g_X\geq 2$.
\begin{enumerate}

\item There exists an irreducible metric on $X$ representing some effective divisor linearly equivalent to $D$.

\item If $d> 12g_{X} - 7$, then the effective divisors as above form an arcwise connected Borel subset of Hausdorff dimension $\geq 2(d+3-4g_X)$ in $|D|$, and all the effective divisors of degree $d$ represented by irreducible metrics form an arcwise connected Borel subset of Hausdorff dimension $\geq 2(d+3-3g_X)$ in ${\rm Sym}^d(X)$.
\end{enumerate}

Two such trivializations, after refinement of the covering if necessary, $\{U_{\alpha}, \psi_{\alpha}\}$ and $\{U_{\alpha}, \tilde{\psi}_{\alpha} \}$ are called equivalent if there exists a collection of maps $\varphi_{\alpha}\colon U_{\alpha} \times \mathbb{P}^r \rightarrow U_{\alpha} \times \mathbb{P}^r$ such that
\begin{itemize}
  \item $\varphi_{\alpha}(x, v)=\big( x, g_{\alpha}(x) \cdot v \big)$, where $g_{\alpha}\colon U_{\alpha} \rightarrow {\rm PSU}(r+1)$ is constant.
  \item For any $\alpha$ and $\beta$, $\varphi_{\alpha} \circ \psi_{\alpha} \circ \psi_{\beta} ^{-1} = \tilde{\psi}_{\alpha} \circ \tilde{\psi}_{\beta} ^{-1}\circ \varphi_{\beta}$ on $\psi_{\beta}(P|_{U_{\alpha} \cap U_{\beta}})$.
\end{itemize}

Looking at $P$ as a holomorphic $\mathbb{P}^{r}$-bundle, we define a {\it holomorphic automorphism of $P$} by a collection of maps $\phi_{\alpha}\colon U_{\alpha} \times \mathbb{P}^r \rightarrow U_{\alpha} \times \mathbb{P}^r$ such that
\begin{itemize}
  \item $\phi_{\alpha}(x, v)=\big( x, g_{\alpha}(x) \cdot v \big)$, where $g_{\alpha}\colon U_{\alpha} \rightarrow {\rm PGL}(r+1, \mathbb{C})$ is holomorphic.
  \item For any $\alpha$ and $\beta$, $\phi_{\alpha} \circ \psi_{\alpha} \circ \psi_{\beta} ^{-1} = \psi_{\alpha} \circ \psi_{\beta} ^{-1}\circ \phi_{\beta}$ on $\psi_{\beta}(P|_{U_{\alpha} \cap U_{\beta}})$.
\end{itemize}

Consider cone spherical metrics representing effective divisors on a compact Riemann surface $X$ of genus $g_{X} \geq 0$. Then there exists the following one-to-one correspondence
\[ \left \{ \begin{array}{c} \begin{tabular}{p{9em}}
Cone spherical metric $g$ representing an effective divisor.
\end{tabular}\end{array}\right \} \leftrightarrow
\left \{ \begin{array}{c} \begin{tabular}{p{13em}}
The pair $(P, s)$, where $P$ is a projective unitary flat $\mathbb P^{1}$-bundle and the section $s \colon X \to P$ is not locally flat.
\end{tabular}\end{array} \right \} \Big/ \operatorname{Aut}_{X}^{u}(P) \]
Note that $P = \mathbb P(E)$ for some rank two vector bundle $E$ since $X$ is a Riemann surface.
\begin{itemize}
\item If $g$ is an irreducible metric representing an effective divisor of even {\rm (}resp. odd{\rm )} degree, then $E$ is a stable vector bundle of even {\rm (}resp. odd{\rm )} degree.
\item If $g$ is reducible, then $E \cong (J \oplus J^{-1})\otimes L$ for some flat line bundle $J$ and some line bundle $L$ on $X$.
\end{itemize}
In summary, $E$ is a rank two polystable vector bundle on $X$.

Let $P$ be an indigenous bundle on a compact Riemann surface $X$ of genus $g_{X} \geq 0$ associated to a branched projective covering $\{U_{\alpha}, w_{\alpha}\}$. Then
\begin{enumerate}
\item If $P = \mathbb P(E)$ for some rank $2$ vector bundle on $X$ and $L$ is the line subbundle of $E$ which is the preimage of the section $s = \{w_{\alpha}\} \colon X \to P$, then $\mathcal O_{X} \left(B_{\{U_{\alpha},w_{\alpha}\}}\right) = L^{-2} \otimes \det E \otimes K_{X}$.
\item The ramification divisor $B_{\{U_{\alpha},w_{\alpha}\}}$ is of even degree if and only if $P = \mathbb{P}(E)$ for some flat rank two vector bundle $E$ with $\det E = \mathcal{O}_X$. Under this context,  there exists a meromorphic section ${\mathfrak s} = \{({\mathfrak s}_{1, \alpha}, {\mathfrak s}_{2,\alpha})\}$ of $E$ such that $w_{\alpha} = [{\mathfrak s}_{1,\alpha}:{\mathfrak s}_{2,\alpha}].$
\end{enumerate}

Since $\{U_{\alpha}, w_{\alpha}\}$ is a branched projective covering on $X$, we could choose a holomorphic coordinate covering  $\{U_{\alpha}, z_{\alpha}\}$  of $X$ with trivializations $\psi_{\alpha}\colon P|_{U_{\alpha}} \rightarrow U_{\alpha} \times \mathbb{P}^1$ and a family of matrices
$M_{\alpha\beta} = \begin{pmatrix}
   a_{\alpha\beta} & b_{\alpha\beta} \\
   c_{\alpha\beta} & d_{\alpha\beta}
\end{pmatrix} \in {\rm SL(2, \mathbb{C})}$ on intersections $U_{\alpha} \cap U_{\beta}\not=\emptyset$ such that
\begin{align}

  w_{\alpha} = \frac{a_{\alpha\beta}w_{\beta} + b_{\alpha\beta}}{c_{\alpha\beta}w_{\beta} + d_{\alpha\beta}}
\end{align}
and $w_\alpha=w_{\alpha}(z_{\alpha})\colon U_\alpha\to {\mathbb C}$ are holomorphic functions by using suitable M{\" o}bius transformations if necessary. Hence we have
$\frac{dw_{\alpha}}{dw_{\beta}} = \frac{1}{(c_{\alpha\beta}w_{\beta}+d_{\alpha\beta})^2}$.
Since $K_X$ is defined by the transition functions
$k_{\alpha\beta} = \frac{dz_{\beta}}{dz_{\alpha}}$,
we have
\[ \lambda_{\alpha\beta} := (c_{\alpha\beta}w_{\beta}+d_{\alpha\beta})^2 = \frac{w_{\beta}'(z_{\beta})} {w_{\alpha}'(z_{\alpha})} \cdot \frac{dz_{\beta}}{dz_{\alpha}} = h_{\alpha\beta}k_{\alpha\beta}, \quad \text{where}\quad
h_{\alpha\beta} = \frac{w_{\beta}'(z_{\beta})} {w_{\alpha}'(z_{\alpha})}.\]
Let $H$ be the line bundle defined by the transition functions $h_{\alpha\beta}$. Then
$\{U_{\alpha}, \frac{1}{w_{\alpha}'(z_{\alpha})}\}$ forms a meromorphic section of $H$ so that
$H = \mathcal{O}_{X}\big(-B_{\{U_{\alpha}, w_{\alpha}\}}\big)$. Hence, for the first assertion, we only need to show $L^{2} = \Lambda \otimes \det E$, where $\Lambda$ is the line bundle defined by transition functions $\lambda_{\alpha \beta}$.

We choose a new holomorphic trivialization of $P|_{U_{\alpha}}$ as follows:
\begin{align*}
\phi_{\alpha} = \mu_{\alpha} \circ \psi_{\alpha} \colon P|_{U_{\alpha}} \xrightarrow{\psi_{\alpha}} U_{\alpha} \times \mathbb{P}^1 &\xrightarrow{\mu_{\alpha}} U_{\alpha} \times \mathbb{P}^1, \\
\text{where } \; \mu_{\alpha}(p, v) &= \left(p, \frac{1}{v - w_{\alpha}(p)}\right).
\end{align*}
Then, with respect to the new trivializations, the section $s=\{w_\alpha\}$ turns out to be $s = [1:0]$. Moreover,  we could obtain by computation that the corresponding transition functions have the form of
\[ \phi_{\alpha \beta}(p) \cdot v = (c_{\alpha \beta}w_{\beta} + d_{\alpha \beta})^{2} \ v + c_{\alpha \beta}(c_{\alpha \beta}w_{\beta} + d_{\alpha \beta}), \quad \forall p \in U_{\alpha} \cap U_{\beta}, v \in \mathbb{P}^{1}.\]
Actually, $\phi_{\alpha \beta}$ is defined by
\begin{align*}
\big(p, \, \phi_{\alpha \beta}(p) \cdot v \big) &= \phi_{\alpha} \circ \phi_{\beta}^{-1}(p, v) = \mu_{\alpha} \circ \psi_{\alpha} \circ \psi_{\beta}^{-1} \circ \mu_{\beta}^{-1}(p, v) \\
&= \mu_{\alpha} \circ (\psi_{\alpha} \circ \psi_{\beta}^{-1}) \left( p, \; w_{\beta} + \frac{1}{v} \right) \\
&= \mu_{\alpha} \left( p,\; \frac{(a_{\alpha \beta} w_{\beta} + b_{\alpha \beta}) \ v + a_{\alpha \beta}}{(c_{\alpha \beta} w_{\beta} + d_{\alpha \beta}) \ v + c_{\alpha \beta}} \right) \\
&= \left( p, \; \frac{1}{\frac{(a_{\alpha \beta} w_{\beta} + b_{\alpha \beta}) \ v + a_{\alpha \beta}}{(c_{\alpha \beta} w_{\beta} + d_{\alpha \beta}) \ v + c_{\alpha \beta}} - w_{\alpha} }\right) \\
&= \left( p, \; \frac{(c_{\alpha \beta} w_{\beta} + d_{\alpha \beta}) \ v + c_{\alpha \beta}}{a_{\alpha \beta} - c_{\alpha \beta} w_{\alpha}} \right) \quad \text{since} \; w_{\alpha} = \frac{a_{\alpha\beta}w_{\beta} + b_{\alpha\beta}}{c_{\alpha\beta}w_{\beta} + d_{\alpha\beta}} \\
&= \left( p, \; \frac{ \big( (c_{\alpha \beta} w_{\beta} + d_{\alpha \beta}) \ v + c_{\alpha \beta} \big) (c_{\alpha \beta} w_{\beta} + d_{\alpha \beta})}{a_{\alpha \beta} (c_{\alpha \beta} w_{\beta} + d_{\alpha \beta}) - c_{\alpha \beta} (a_{\alpha\beta}w_{\beta} + b_{\alpha\beta})} \right) \\
&= \left( p, \; (c_{\alpha \beta}w_{\beta} + d_{\alpha \beta})^{2} \ v + c_{\alpha \beta}(c_{\alpha \beta}w_{\beta} + d_{\alpha \beta}) \right).
\end{align*}

On the other hand,  let $\ell_{\alpha \beta}$ be the transition functions of $L$. Then the transition functions of $E$ look like
\[ \begin{pmatrix}
  \ell_{\alpha \beta} & t_{\alpha \beta} \\
   0 & \ell_{\alpha \beta}^{-1} \xi_{\alpha \beta}
\end{pmatrix}, \]
where $\xi = \det E$. Hence, $g_{\alpha \beta}(p) \cdot v = \ell_{\alpha \beta}^{2} \xi^{-1}_{\alpha \beta} \ v + \ell_{\alpha \beta}\xi^{-1}_{\alpha \beta} t_{\alpha \beta}$ is a transition function of $P$. Moreover, $s = [1:0]$ since it is defined by $L \to E$.

Note that the $\mathbb P^{1}$-bundles defined by $\phi_{\alpha \beta}$ and $g_{\alpha \beta}$ are holomorphically equivalent. Let $\varphi_{\alpha}\colon U_{\alpha} \times \mathbb P^{1} \rightarrow U_{\alpha} \times \mathbb P^{1}$ be a  1-coboundary with $\varphi_{\alpha}(p, v) = \big(p, g_{\alpha}(p) \cdot v \big)$ \cite[p.409]{Atiyah55}. Then $g_{\alpha} \cdot \big( [1:0] \big) = [1:0]$, i.e. $g_{\alpha}$ is an affine transformation. Let $g_{\alpha} \cdot v = A_{\alpha}\, v + B_{\alpha}\ (A_{\alpha} \neq 0, v \in \mathbb P^{1} \setminus \{ \infty \})$, by
\[ \phi_{\alpha \beta} = g_{\alpha} \circ g_{\alpha \beta} \circ g_{\beta}^{-1} \ \text{ on } U_{\alpha} \cap U_{\beta}, \]
we obtain that $(c_{\alpha \beta}w_{\beta} + d_{\alpha \beta})^{2} = A_{\alpha} \, \ell_{\alpha \beta}^{2} \xi^{-1}_{\alpha \beta} \, A_{\beta}^{-1}$. Therefore, line bundles defined by $(c_{\alpha \beta}w_{\beta} + d_{\alpha \beta})^{2}$ and $\ell_{\alpha \beta}^{2} \xi^{-1}_{\alpha \beta}$ are equivalent, i.e. $\Lambda = L^{2} \otimes (\det E)^{-1}$.

For the second part, note that $H$ has degree $\left(-\deg B_{\{U_{\alpha}, w_{\alpha}\}}\right)$ and the line bundle $\Lambda$ has degree $\left(2g_{X} - 2 - \deg B_{\{U_{\alpha}, w_{\alpha}\}}\right)$.

Suppose that $\deg B_{\{U_{\alpha}, w_{\alpha}\}}$ is even. Then so is $\deg \Lambda$. There exists a line bundle $N$ defined by $N_{\alpha\beta}$ such that $N_{\alpha\beta}^2 = \lambda_{\alpha\beta}$. By changing the sign of $M_{\alpha\beta}\in {\rm SL(2,\,{\mathbb C})}$ if necessary,  we have $N_{\alpha\beta} = c_{\alpha\beta}w_{\beta} + d_{\alpha\beta}$. Taking a non-trivial  meromorphic section $\{U_{\alpha}, f_{\alpha}\}$ of $N$, we find
\[ \begin{pmatrix}
  w_{\alpha}f_{\alpha} \\
  f_{\alpha}
\end{pmatrix} = \begin{pmatrix}
  a_{\alpha\beta} & b_{\alpha\beta} \\
  c_{\alpha\beta} & d_{\alpha\beta}
\end{pmatrix} \begin{pmatrix}
  w_{\beta}f_{\beta} \\
  f_{\beta}
\end{pmatrix} \]
and $M_{\alpha\beta} = M_{\alpha\gamma} M_{\gamma\beta}$. The desired flat rank two vector bundle $E$ is just the one defined by $M_{\alpha\beta}$. Furthermore,  $(w_{\alpha}f_{\alpha}, f_{\alpha})$ forms a meromorphic section ${\mathfrak s}=({\mathfrak s}_{1,\alpha},\,{\mathfrak s}_{2,\alpha})$ of $E$ satisfying $w_\alpha=[{\mathfrak s}_{1,\alpha} : {\mathfrak s}_{2,\alpha}]$.

Suppose that there exists a rank two flat vector bundle $E$ with ${\mathbb P}(E)=P$ for the indigenous bundle $P$ which is associated to the projective covering $\{(U_\alpha,\,w_\alpha)\}$. Then $s = \{w_\alpha\}$ is the canonical section of $P$. By the argument in the first paragraph of \cite[Section 4]{Atiyah57II}, there exists a line subbundle $L$ of $E$ generated by $s$ such that each non-trivial meromorphic section ${\mathfrak s}=\big({\mathfrak s}_{1,\alpha},\,{\mathfrak s}_{2,\,\alpha}\big)$ of the line bundle $L\subset E$ satisfies $w_\alpha=[{\mathfrak s}_{1,\alpha} : {\mathfrak s}_{2,\alpha}]$. Denote by
$ M_{\alpha\beta} = \begin{pmatrix}
   a_{\alpha\beta} & b_{\alpha\beta} \\
   c_{\alpha\beta} & d_{\alpha\beta}
\end{pmatrix} \in {\rm SL(2, \mathbb{C})}$
the transition functions of $E$. Recalling \eqref{wtransition} in the first paragraph of the proof, we only need to show the degree of the line bundle $\Lambda$ is even since $\Lambda = H \otimes K_X$ and
\[ \deg\, B_{\{U_\alpha,\,w_\alpha\}}\equiv \deg\, H\quad (\text{mod}\ 2).\]
Since
$w_\alpha = [{\mathfrak s}_{1,\alpha} :{\mathfrak s}_{2,\alpha}]$, we have
\[ \begin{pmatrix}
  w_{\alpha}{\mathfrak s}_{2,\alpha} \\
  {\mathfrak s}_{2,\alpha}
\end{pmatrix} = \begin{pmatrix}
  {\mathfrak s}_{1,\alpha} \\
  {\mathfrak s}_{2,\alpha}
\end{pmatrix} = \begin{pmatrix}
  a_{\alpha\beta} & b_{\alpha\beta} \\
  c_{\alpha\beta} & d_{\alpha\beta}
\end{pmatrix} \begin{pmatrix}
 {\mathfrak s}_{1,\beta} \\
  {\mathfrak s}_{2,\beta}
\end{pmatrix} = \begin{pmatrix}
  a_{\alpha\beta} & b_{\alpha\beta} \\
  c_{\alpha\beta} & d_{\alpha\beta}
\end{pmatrix} \begin{pmatrix}
  w_{\beta}{\mathfrak s}_{2,\beta} \\
  {\mathfrak s}_{2,\beta}
\end{pmatrix} \]
and ${\mathfrak s}_{2, \alpha} = (c_{\alpha\beta}w_{\beta} + d_{\alpha\beta}) {\mathfrak s}_{2,\beta}$. It follows that the functions $\left(c_{\alpha\beta}w_{\beta} + d_{\alpha\beta}\right)$ on $U_{\alpha} \cap U_{\beta}$ are 1-cocyles, which define a line bundle $N$ with $N^2 = \Lambda$. Hence, $\deg \Lambda$ is even.

Let $D$ be an effective divisor represented by a cone spherical metric $g$ on a compact Riemann surface $X$ of genus $g_X\geq 0$. Then $\deg D$ is even if and only if the monodromy representation $\rho_f\colon \pi_1(X)\to {\rm PSU(2)}$ of a developing map $f$ of $g$ could be lifted to $\widetilde{\rho_f}\colon \pi_1(X)\to {\rm SU}(2)$ with the following commutative diagram
\[ \xymatrix{
  \pi_{1}(X) \ar[r]^{\widetilde{\rho_f}} \ar[rd]_{\rho _{f}} & {\rm SU(2)} \ar[d] ^{\pi} \\
                                                                                & {\rm PSU(2)}.
} \]

also_stated_at:
Recalling the universal (double) covering $\pi \colon {\rm SU(2)}\to {\rm PSU(2)}$, we make an observation (Corollary \ref{cor:criterion}) that an effective divisor $D$ represented by a cone spherical metric $g$ on $X$ has {\it even} degree if and only if the monodromy representation $\rho_f \colon \, \pi_1(X) \to {\rm PSU(2)}$ of a developing map $f$ of the metric $g$ could be lifted to a group homomorphism $\widetilde{\rho_f} \colon \, \pi_1(X) \to {\rm SU}(2)$ such that there holds the following commutative diagram
\[ \xymatrix{
                                                                                   & {\rm SU(2)} \ar[d] ^{\pi} \\
\pi_{1}(X) \ar[ru]^{\widetilde{\rho_f}} \ar[r]_{\rho_{f}} & {\rm PSU(2)}.
}\]

nodes.statement:
Two embeddings $L \xrightarrow{i} E$ and $L' \xrightarrow{i'} E'$ are called {\it equivalent} if there exists a line bundle $N$ on $X$ with the following commutative diagram
\[ \xymatrix{
L \otimes N \ar@{=}[d] \ar[r]^{i \otimes \operatorname{id}_{N}} & E \otimes N \ar@{=}[d] \\
L'                \ar[r]^{i'}                   & E'.
} \]

{\bfseries Claim 2}: {\it If $s \in H^{0}(X, L^{-1} \otimes E)$ is a generic section, then $s$ is nowhere vanishing and gives a stable embedding $L\to E$.}
\vspace{5pt}

In fact, since $L^{-1}\otimes E$ is ample in the sense of Atiyah op.cit., we have that $L^{-1}\otimes E$ is globally generated, i.e. $$H^{0}(X, L^{-1} \otimes E) \xrightarrow{\operatorname{ev}_{x}} E|_{\{x\}},\; s \mapsto s(x)$$ is an epimorphism for each $x \in X$. Let $K_{x} = \ker (\operatorname{ev}_{x})$, and let $S$ be the subvariety of  $H^{0}(X, L^{-1} \otimes E)$ generated by all $K_{x}$'s. Then we have
\begin{eqnarray*}
\dim S &\leq& \Big(\dim H^{0}(X, L^{-1} \otimes E) - \dim E|_{\{x\}}\Big) + \dim X \\&=&
 \dim H^{0}(X, L^{-1} \otimes E) - 1.
 \end{eqnarray*}
Hence, if $s \in H^{0}(X, L^{-1} \otimes E)$ is a generic section, then $s \notin S$, i.e. $s$ is a nowhere vanishing section, which induces an embedding of $L$ into $E$ since $\mathcal{H}om(L,\,E)\cong L^{-1}\otimes E$.
Hence we complete the proof of the second claim.

By the Serre duality and the Riemann-Roch theorem, we have
\begin{align*}
\dim \mathcal{R} &= \dim \operatorname{Ext}_{X}^{1}(L, \mathcal O_{X}) -1 \\
&= \dim H^{1}(X, L^{-1}) - 1 \\
&= d + g_{X} - 2.
\end{align*}

\begin{split} \xymatrix{
 L\ar[r] ^-{i}\ar[drr]_-{\theta_{\mathbb E}} & E\ar[r] ^-{\partial_{E}} & E\otimes K_{X}\ar[d]^-{p \otimes \operatorname{id}} \\
           & & L^{-1}\otimes K_{X},
} \end{split}

{\rm

Suppose $E$ is a polystable vector bundle of rank two with $\det E = \mathcal O_{X}$, and $L$ is a line subbundle of $E$ such that the section $s_{(L, E)} = \{ U_{\alpha}, w_{\alpha} \} \colon X \to \mathbb P(E)$ is {\it not} locally flat. By a similar argument, the ramification divisor $B_{\{U_{\alpha, w_{\alpha}}\}} = \operatorname{Div}(\theta_{\mathbb E})$.
}

Note that
\begin{equation*}

\begin{split}
\lambda I = D_{E} \circ D_{E} &= \begin{pmatrix}
D_{L} \circ D_{L} - \beta \wedge \beta^{*_{\beta}} & - \left(D_{L} \circ \beta + \beta \circ D_{M}\right) \\
\beta^{*_{\beta}} \circ D_{L} + D_{M} \circ \beta^{*_{\beta}} & -\beta^{*_{\beta}} \wedge \beta + D_{M} \circ D_{M}
\end{pmatrix} \\
&= \begin{pmatrix}
\Theta_{L} - \beta \wedge \beta^{*_{\beta}} & -D_{\mathcal{H}om(M, L)} (\beta)\\
D_{\mathcal{H}om(L, M)}(\beta^{*_{\beta}}) & -\beta^{*_{\beta}} \wedge \beta + \Theta_{M}
\end{pmatrix}.
\end{split}
\end{equation*}
Therefore $D_{L^{-1} \otimes M}(\beta^{*_{\beta}}) = 0$ and then $\bar{\partial}_{L^{-1} \otimes M}(\beta^{*_{\beta}}) = 0$. Hence $\beta^{*_{\beta}}$ is holomorphic which implies that $\theta_{\mathbb E} = \beta^{*_{\beta}} \in \operatorname{Hom}_{\mathcal O_{X}}(L, M \otimes K_{X})$.

Now, we prove the second assertion in Theorem \ref{thm:rami}. At first, we consider a polystable extension ${\Bbb E}:\, 0\to L\to E\to M \to 0$, where $E$ is a rank two polystable vector bundle of even degree. Then there is a line bundle $\eta$ such that $E \otimes \eta^{-1} := E_{0}$ is flat and $\det E_{0} = \mathcal O_{X}$. Moreover, $E/L \cong L^{-1} \otimes \eta^{2}$. Denote by $D_{E}$ and $D_{E_{0}}$ the Chern connections of $E$ and $E_{0}$ respectively. Then
\begin{align*}
\bar{\partial}_{E} & = \bar{\partial}_{E_{0}} \otimes \operatorname{id} + \operatorname{id} \otimes \bar{\partial}_{\eta}, \\
D_{E} & = D_{E_{0}} \otimes \operatorname{id} + \operatorname{id} \otimes D_{\eta}.
\end{align*}
Hence
\[ \partial_{E} = \partial_{E_{0}} \otimes \operatorname{id} + \operatorname{id} \otimes \partial_{\eta}. \]
The commutative diagram
\[\xymatrix{
 \mathcal A^{0}(L)\ar[r] ^-{i}\ar[drr]_-{\theta_{\mathbb E}} & \mathcal A^{0}(E)\ar[r] ^-{\partial_{E}} & E\otimes \mathcal{A}^{1,0}\ar[d]^-{p \otimes \operatorname{id}} \\
  & & L^{-1}\otimes \eta^{2} \otimes \mathcal{A}^{1,0},
}\]
can be rewritten as
\[\xymatrix{
 \mathcal A^{0}(L_{0} \otimes \eta)\ar[r] ^-{i}\ar[drr]_-{\theta_{\mathbb E}} & \mathcal A^{0}(E_{0}\otimes \eta)\ar[r] ^{\partial_{E_{0}} \otimes \operatorname{id} + \operatorname{id} \otimes \partial_{\eta}} & E_{0} \otimes\eta\otimes \mathcal{A}^{1,0}\ar[d]^-{p \otimes \operatorname{id}} \\
  & & {}\phantom{changying}L_{0}^{-1}\otimes \eta \otimes \mathcal{A}^{1,0},\phantom{changying}
}\]
where $L_{0} = L\otimes \eta^{-1}$ is a line subbundle of $E_{0}$. Denote by ${\Bbb E}_0$ the stable extension $0\to L_0\to E_0\to L_0^{-1}\to 0$.

Then $\theta_{\mathbb E} = \theta_{\mathbb E_{0}} \otimes \operatorname{id}_{\eta}$, which means that $\theta_{\mathbb E}$ and $\theta_{\mathbb E_{0}}$ are consistent as a section of $L_{0}^{-2} \otimes K_{X}$. Then, by  Lemma \ref{lem:flatcase}, we know that $D = \operatorname{Div}(\theta_{\mathbb E_{0}}) = \operatorname{Div}(\theta_{\mathbb E})$ since the two embeddings $L \to E$ and $L_{0} \to E_{0}$ are equivalent.



Suppose $E$ is stable and $\deg E$ is odd. Then we consider the \'etale double cover $\pi \colon \widehat{X} \to X$ given by Lemma \ref{lem:doublecover}. Let $\{ U_{\alpha}, w_{\alpha} \}$ be the local expression of $s_{(L,E)}$, which defines a branched projective covering of $X$.  Without loss of generality, we may assume that $U_{\alpha}$ is sufficiently small such that $\left\{\pi^{-1}(U_{\alpha}), \pi^*(w_{\alpha})\right\}$ is a branched projective covering of $\widehat{X}$. Then $\pi^*(\mathbb P(E)) = \mathbb{P}(\pi^*(E))$ is the indigenous bundle associated to $\{\pi^{-1}(U_{\alpha}), \pi^*(w_{\alpha})\}$ and
\[ \pi^{*} B_{\{U_{\alpha}, w_{\alpha}\}} = B_{\{\pi^{-1}(U_{\alpha}), \pi^*(w_{\alpha})\}}. \]
By the following diagram
\[\xymatrix{
 \mathcal A^{0}(\pi^{*}(L))\ar[r] \ar[drr]_-{\theta_{\pi^{*}({\mathbb E})}} & \mathcal A^{0}(\pi^{*}(E))\ar[r] ^{\partial_{\pi^{*}(E)}} & \pi^{*}(E) \otimes \mathcal{A}^{1,0}\ar[d] \\
 & & \pi^{*}(M) \otimes \mathcal{A}^{1,0},
}\]
